ret = (1.0 - abs( GetPixel(uv+vec2( 1.0 , 0.0 )*d)-GetPixel(uv-vec2( 1.0 , 0.0 )*d).xy ).z * 4.0)*GetPixel(uv).z*vec3(0.2,0.5,0.6);
ret= pow(mix(ret, 3.0 ,wires*6.5),0.9);
//ret = GetPixel(uv).y;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float d;
vec3 emboss, dx, dy;
shader_body
{
vec2 uv2 = uv;
if(uv2.x >= 0.5) {uv2.x = 1.0 - uv2.x;}
if(uv2.y >= 0.5) {uv2.y = 1.0 - uv2.y;}
uv.x=uv2.x;
