float d;
float3 emboss, dx, dy;
shader_body
{
float2 uv2 = uv;
if(uv2.x >= 0.5) {uv2.x = 1-uv2.x;}
if(uv2.y >= 0.5) {uv2.y = 1-uv2.y;}
uv.x=uv2.x;
uv.y=uv2.y;
d = texsize.zw*3;
dx = ( GetPixel(uv+float2(1,0)*d)-GetPixel(uv-float2(1,0)*d) )*2;
dy = ( GetPixel(uv+float2(0,1)*d)-GetPixel(uv-float2(0,1)*d) )*2;
float3 wires = (dx.x+dy.x+0.5)*GetBlur3(uv*1).x*float3(0.7,0.5,0);
