dy = GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) ;
uv = uv - float2(dx.x,dy.x)*0.2;
ret = (1-abs( GetPixel(uv+float2(1,0)*d)-GetPixel(uv-float2(1,0)*d) ).z*4)*GetPixel(uv).z*float3(0.2,0.5,0.6);
ret= pow(lerp(ret,3,wires*6.5),0.9);
//ret = GetPixel(uv).y;
}

